//! The licenses shown on the About page.
//!
//! `assets/THIRD_PARTY_LICENSES.txt` is generated by `cargo-about` from every crate Sotto
//! is built with (see `about.toml` / `about.hbs`) and built into the binary. Each entry
//! starts with an `@@license <name>` line and an `@@used-by <crates>` line. The Inter
//! font and the Lucide icons aren't crates, so they're added here from their own
//! license files.
//!
//! The text is split once, the first time the About page opens (`LazyLock` is like a
//! module-level value computed on first access in Python). It borrows from the built-in
//! text, so nothing is copied.

use std::sync::LazyLock;

pub struct License {
    pub name: &'static str,
    pub used_by: &'static str,
    pub text: &'static str,
}

/// Sotto's own license.
pub const GPL: &str = include_str!("../../LICENSE");
const CRATES: &str = include_str!("../../assets/THIRD_PARTY_LICENSES.txt");

pub static ALL: LazyLock<Vec<License>> = LazyLock::new(|| {
    let mut all = vec![
        License {
            name: "SIL Open Font License 1.1",
            used_by: "Inter font",
            text: include_str!("../../assets/fonts/LICENSE-Inter.txt").trim(),
        },
        License {
            name: "ISC License",
            used_by: "Lucide icons",
            text: include_str!("../../assets/icons/LICENSE-lucide.txt").trim(),
        },
    ];
    all.extend(parse(CRATES));
    all
});

/// Split the generated file into entries. Anything malformed is skipped, never a panic.
fn parse(file: &'static str) -> impl Iterator<Item = License> {
    file.split("\n@@license ").skip(1).filter_map(|block| {
        let (name, rest) = block.split_once('\n')?;
        let rest = rest.strip_prefix("@@used-by ")?;
        let (used_by, text) = rest.split_once('\n')?;
        Some(License {
            name: name.trim(),
            used_by: used_by.trim(),
            text: text.trim(),
        })
    })
}

/// Join hard-wrapped lines into paragraphs so the text wraps to the window's width.
/// Lines that start with a space, a bullet or a number ("1.", "(a)") start a new line.
pub fn reflow(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut prev_blank = true;
    // An all-caps line ("PREAMBLE") is a heading: the next line starts below it.
    let mut prev_heading = false;
    for line in text.lines() {
        let t = line.trim_end();
        if t.is_empty() {
            if !prev_blank {
                out.push_str("\n\n");
            }
            prev_blank = true;
            prev_heading = false;
            continue;
        }
        let numbered = t.split_once('.').is_some_and(|(n, _)| {
            !n.is_empty() && n.len() <= 3 && n.chars().all(|c| c.is_ascii_alphanumeric())
        });
        let starts_item = numbered || t.starts_with([' ', '\t', '-', '*', '\u{2022}', '(', '#']);
        if !prev_blank {
            out.push(if starts_item || prev_heading {
                '\n'
            } else {
                ' '
            });
        }
        out.push_str(t.trim_start());
        prev_blank = false;
        prev_heading = t.chars().any(char::is_alphabetic) && !t.chars().any(char::is_lowercase);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_entry_is_complete() {
        assert!(ALL.len() > 100, "{} entries", ALL.len());
        for l in ALL.iter() {
            assert!(!l.name.is_empty() && !l.used_by.is_empty() && !l.text.is_empty());
            assert!(!l.text.contains("@@license"), "{}", l.name);
            // Escaped HTML means the template used {{ }} instead of {{{ }}}.
            assert!(!l.text.contains("&quot;"), "{}", l.name);
        }
    }

    #[test]
    fn reflow_joins_wrapped_lines_and_keeps_paragraphs_and_lists() {
        let t = "PREAMBLE\nThe goals.\n\nPermission is hereby\ngranted, free of charge.\n\n1. Definitions.\n   (a) one\n- two\nend\n";
        assert_eq!(
            reflow(t),
            "PREAMBLE\nThe goals.\n\nPermission is hereby granted, free of charge.\n\n1. Definitions.\n(a) one\n- two end"
        );
    }

    #[test]
    fn the_main_parts_are_credited() {
        for who in [
            "nnnoiseless",
            "deep_filter",
            "cpal",
            "gpui",
            "Inter font",
            "Lucide",
        ] {
            assert!(
                ALL.iter().any(|l| l.used_by.contains(who)),
                "{who} has no license entry"
            );
        }
        assert!(GPL.contains("GNU GENERAL PUBLIC LICENSE"));
    }
}
